mapper.update:
UPDATE cake_stocks
SET quantity = quantity + 1,
    updated_at = NOW()
WHERE cake_id = #{cakeId}
  AND cake_size = #{cakeSize}

mapper.select:
SELECT quantity
FROM cake_stocks
WHERE cake_id = #{cakeId}
  AND cake_size = #{cakeSize}
FOR UPDATE

mapper.update:
UPDATE cake_stocks
SET quantity = quantity - 1,
    updated_at = NOW()
WHERE cake_id = #{cakeId}
  AND cake_size = #{cakeSize}
  AND quantity > 0
